"use client";
import { useEffect, useRef, useState } from "react";
import "./ascii-tide.css";

const ramp = " .,-~:;=+*#%@";
const LEVELS = 14;
const rgb = (hex: string) => {
  const h = /^#[0-9a-f]{6}$/i.test(hex) ? hex : "#8ab4ff";
  return [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
};
/** A night sea in dense characters: slope-lit water, fog at the horizon, a moonlit glint. */
export function AsciiTide({
  color = "#8ab4ff",
  speed = 1,
  label = "Slow waves drawn in dense characters",
}: {
  color?: string;
  speed?: number;
  label?: string;
}) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const [paused, setPaused] = useState(false);
  useEffect(() => {
    const node = canvas.current!,
      context = node.getContext("2d");
    if (!context) return;
    const media = matchMedia("(prefers-reduced-motion:reduce)");
    const tint = rgb(color);
    const palette = Array.from({ length: LEVELS }, (_, i) => {
      const k = i / (LEVELS - 1);
      // Deep tint in the troughs, the color itself mid-swell, near white on crests.
      const mix = (c: number) =>
        k < 0.6 ? Math.round(c * (0.22 + (k / 0.6) * 0.78)) : Math.round(c + (255 - c) * ((k - 0.6) / 0.4) * 0.9);
      return `rgb(${mix(tint[0])},${mix(tint[1])},${mix(tint[2])})`;
    });
    const fontSize = 8;
    let frame = 0,
      visible = false,
      last = performance.now(),
      t = 0,
      width = 0,
      height = 0,
      cellW = 4.8;
    const wave = (a: number, b: number) =>
      Math.sin(a * 0.9 + b * 1.2 + t * 0.5) +
      0.5 * Math.sin(a * 1.9 - b * 2.1 - t * 0.7) +
      0.25 * Math.sin(a * 3.7 + b * 4.3 + t * 1.1) +
      0.12 * Math.sin(a * 7.1 - b * 8.7 - t * 1.6);
    const paint = (now: number) => {
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;
      if (!paused && !media.matches) t += dt * Math.max(0, Math.min(speed, 3));
      context.fillStyle = "#030406";
      context.fillRect(0, 0, width, height);
      const cols = Math.ceil(width / cellW),
        rows = Math.ceil(height / fontSize),
        aspect = width / height;
      const lines: string[][] = Array.from({ length: LEVELS }, () => []);
      for (let row = 0; row < rows; row++) {
        const y = row / rows;
        const parts: string[][] = Array.from({ length: LEVELS }, () => []);
        for (let col = 0; col < cols; col++) {
          const x = (col / cols - 0.5) * aspect * 2;
          // A sea in perspective: each cell below the horizon is a point on the water,
          // shaded by its slope, fading into fog with a moonlit glint down the middle.
          const v = (y - 0.28) / 0.72;
          let k = 0;
          if (v > 0) {
            const z = 1 / (v + 0.045);
            const wx = x * z * 1.5;
            const light = Math.max(0, Math.min(1, 0.42 + (wave(wx, z * 2.2 + 0.09) - wave(wx, z * 2.2)) * 3.6));
            const fog = 1 - Math.exp(-v * 7);
            const glint = Math.exp(-x * x * (1.1 + 5 * (1 - v))) * Math.pow(light, 1.6) * 1.15;
            k = Math.min(1, fog * (0.08 + 0.7 * light * light) + glint * (0.35 + 0.65 * Math.min(1, v * 3)));
          } else {
            k = 0.16 * Math.exp(v * 26) * Math.exp(-x * x * 0.5);
          }
          const level = Math.min(LEVELS - 1, Math.floor(k * LEVELS));
          const ch = k < 0.03 ? " " : ramp[Math.min(ramp.length - 1, 1 + Math.floor(k * (ramp.length - 1)))];
          for (let l = 0; l < LEVELS; l++) parts[l].push(l === level ? ch : " ");
        }
        for (let l = 0; l < LEVELS; l++) lines[l].push(parts[l].join(""));
      }
      for (let l = 0; l < LEVELS; l++) {
        context.fillStyle = palette[l];
        for (let row = 0; row < lines[l].length; row++)
          if (lines[l][row].trim()) context.fillText(lines[l][row], 0, row * fontSize);
      }
    };
    const tick = (now: number) => {
      if (now - last >= 40) paint(now);
      frame = requestAnimationFrame(tick);
    };
    const start = () => {
      cancelAnimationFrame(frame);
      last = performance.now();
      paint(last);
      if (visible && !document.hidden && !paused && !media.matches) frame = requestAnimationFrame(tick);
    };
    const resize = new ResizeObserver(() => {
      const rect = node.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      const ratio = Math.min(devicePixelRatio || 1, 2);
      node.width = Math.round(width * ratio);
      node.height = Math.round(height * ratio);
      context.setTransform(ratio, 0, 0, ratio, 0, 0);
      context.font = `500 ${fontSize}px ui-monospace, SFMono-Regular, Menlo, monospace`;
      context.textBaseline = "top";
      cellW = context.measureText("M").width;
      start();
    });
    resize.observe(node);
    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      start();
    });
    observer.observe(node);
    document.addEventListener("visibilitychange", start);
    media.addEventListener("change", start);
    return () => {
      cancelAnimationFrame(frame);
      resize.disconnect();
      observer.disconnect();
      document.removeEventListener("visibilitychange", start);
      media.removeEventListener("change", start);
    };
  }, [color, speed, paused]);
  return (
    <div className="forme-ascii-tide">
      <canvas ref={canvas} role="img" aria-label={label} />
      <div className="forme-ascii-tide-footer">
        <button aria-pressed={paused} onClick={() => setPaused(!paused)}>
          {paused ? "Resume" : "Pause"}
        </button>
      </div>
    </div>
  );
}

.forme-ascii-tide {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 120px;
  background: #030406;
  overflow: hidden;
}
.forme-ascii-tide canvas {
  display: block;
  width: 100%;
  height: 100%;
}
.forme-ascii-tide-footer {
  position: absolute;
  right: 14px;
  bottom: 14px;
  font: 500 12px/1 system-ui, sans-serif;
}
.forme-ascii-tide-footer button {
  height: 26px;
  padding: 0 11px;
  border: 1px solid #ffffff1f;
  border-radius: 999px;
  background: #00000080;
  backdrop-filter: blur(8px);
  color: #e4e4e7;
  font: inherit;
  cursor: pointer;
}
.forme-ascii-tide-footer button:focus-visible {
  outline: 2px solid #e4e4e7;
  outline-offset: 3px;
}
@media (prefers-reduced-motion: reduce) {
  .forme-ascii-tide-footer button {
    transition: none;
  }
}
